const { chromium } = require("playwright");

const DEFAULT_WAIT_MS = Number(process.env.DEFAULT_WAIT_MS || 2000);
const USERNAME = process.env.USERNAME || "admin";
const LOGINCREDENTIAL = process.env.LOGINCREDENTIAL || "admin";

async function findSearchInput(page) {
  const selectors = [
    'input[type="search"]',
    'textarea[name="q"]',
    'input[name="q"]',
    'input[name="wd"]',
    'textarea[name="wd"]',
    '[role="searchbox"]',
    'input[placeholder*="搜索"]',
    'input[placeholder*="Search" i]',
    'textarea[placeholder*="搜索"]',
    'textarea[placeholder*="Search" i]',
  ];
  for (const selector of selectors) {
    const locator = page.locator(selector).first();
    if (await locator.count()) {
      return locator;
    }
  }
  throw new Error("No search input found on current page");
}

async function clickSearchResult(page, context, index) {
  const selectors = [
    "#content_left a[href]",
    "#b_results a[href]",
    "main a[href]",
    "a[href]"
  ];
  for (const selector of selectors) {
    const links = page.locator(selector);
    const count = await links.count();
    if (count >= index) {
      const popupPromise = page.waitForEvent("popup", { timeout: 3000 }).catch(() => null);
      await links.nth(index - 1).click();
      const popup = await popupPromise;
      const nextPage = popup || context.pages().at(-1) || page;
      await nextPage.waitForLoadState("domcontentloaded").catch(() => {});
      return nextPage;
    }
  }
  throw new Error(`Search result index out of range: ${index}`);
}

async function run() {
  const browser = await chromium.launch({ headless: false });
  const context = await browser.newContext();
  let page = await context.newPage();

  // Step 1: 打开登录页
  await page.goto("http://192.168.100.143/#approvals");
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 2: 填写用户名 admin
  await page.getByRole('textbox', { name: 'ユーザー名 (Username)' }).first().fill(USERNAME);
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 3: 填写密码 admin
  await page.getByRole('textbox', { name: 'パスワード (Password)' }).first().fill(LOGINCREDENTIAL);
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 4: 点击登录按钮(ref=e16,精确匹配,避免文本'登录'误匹配日语'ログイン')
  await page.locator("e16").first().click();
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 5: 点击'保留中'按钮筛选未批准的数据
  await page.getByRole('button', { name: '保留中' }).first().click();
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 6: 点击第一个记录，进入详细页面
  await page.getByText(":nth-match([data-ai-action=\"detail\"], 1)", { exact: false }).first().click();
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 7: 粗利率大于20%时自动点击承认按钮
  await page.getByTestId('btn-approve').first().click();
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 8: 截图确认当前页面状态
  await page.screenshot({ path: "artifacts/step-8.png", fullPage: true });
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  // Step 9: 点击「一覧に戻る」按钮返回案件列表
  await page.locator("e189").first().click();
  await page.waitForTimeout(DEFAULT_WAIT_MS);

  await page.waitForTimeout(5000);
  await browser.close();
}

run().catch((error) => {
  console.error(error);
  process.exit(1);
});
